# Beta event list (sketch)
from datetime import date
def filter_upcoming(events):
    today = date.today().isoformat()
    return [e for e in events if e["date"] >= today]
def sort_by_distance(events, lat, lon):
    return sorted(events, key=lambda e: abs(e["lat"] - lat) + abs(e["lon"] - lon))
